import type { ButtonHTMLAttributes, ReactNode } from "react"
import { Sparkles } from "lucide-react"
import { twMerge } from "tailwind-merge"
import "./button-01.css"

export type Button01Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  icon?: ReactNode
}

export function Button01({
  children = "Publish",
  className,
  icon = <Sparkles aria-hidden="true" className="size-7 shrink-0 stroke-[2.1]" />,
  type = "button",
  ...props
}: Button01Props) {
  return (
    <button
      type={type}
      className={twMerge(
        "button-01-border-flow relative isolate inline-flex h-[74px] min-w-[186px] cursor-pointer items-center justify-center gap-3 overflow-hidden rounded-full border border-[#639af0] bg-[radial-gradient(circle_at_72%_-20%,rgba(112,172,255,0.16),transparent_48%),linear-gradient(105deg,#394f7d_0%,#17458f_48%,#0d4db5_100%)] px-10 text-xl font-semibold leading-none tracking-[-0.025em] text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.16),inset_0_-1px_0_rgba(0,29,86,0.72),0_0_0_1px_rgba(27,99,238,0.24),0_8px_22px_rgba(0,0,0,0.5),0_0_16px_rgba(15,85,205,0.12)] transition-all duration-200 hover:-translate-y-0.5 hover:brightness-110 hover:shadow-[inset_0_1px_0_rgba(255,255,255,0.22),inset_0_-1px_0_rgba(0,29,86,0.62),0_0_0_1px_rgba(83,150,255,0.44),0_12px_28px_rgba(0,0,0,0.52),0_0_24px_rgba(36,111,244,0.24)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-300 focus-visible:ring-offset-2 focus-visible:ring-offset-[#080c0f] active:translate-y-0 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    >
      {icon}
      {children}
    </button>
  )
}

export default Button01

@property --button-01-border-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes button-01-border-flow {
  to {
    --button-01-border-angle: 360deg;
  }
}

.button-01-border-flow::before {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--button-01-border-angle),
    transparent 0deg 230deg,
    rgb(77 151 255 / 0.08) 250deg,
    rgb(106 172 255 / 0.7) 276deg,
    rgb(232 248 255 / 1) 302deg,
    rgb(89 157 255 / 0.82) 326deg,
    transparent 350deg 360deg
  );
  content: "";
  pointer-events: none;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation: button-01-border-flow 2.8s linear infinite;
}

.button-01-border-flow:disabled::before {
  opacity: 0.45;
  animation-play-state: paused;
}

@media (prefers-reduced-motion: reduce) {
  .button-01-border-flow::before {
    animation: none;
  }
}
